#!/usr/bin/env bash
set -euo pipefail
WORKSPACE="/home/kavia/workspace/code-generation/note-organizer-206538-206547/notes_native_app"
cd "$WORKSPACE"
ELECTRON_VER="25.2.0"
# create package.json if missing or incomplete
if [ ! -f package.json ]; then cat > package.json <<JSON
{
  "name": "notes_native_app",
  "version": "0.1.0",
  "main": "src/main.js",
  "license": "MIT",
  "scripts": {
    "build": "webpack --config webpack.renderer.js --mode=production",
    "start": "node ./start.sh",
    "test": "jest --runInBand"
  },
  "devDependencies": {
    "electron": "25.2.0",
    "webpack": "5.88.2",
    "webpack-cli": "5.1.4",
    "jest": "29.7.0"
  },
  "dependencies": {
    "sqlite3": "5.1.6"
  }
}
JSON
fi
mkdir -p src renderer __tests__
# ensure src/main.js exists
if [ ! -f src/main.js ]; then cat > src/main.js <<'JS'
const {app, BrowserWindow} = require('electron');
const fs = require('fs');
const path = require('path');
const OUT = path.join(process.cwd(),'startup.txt');
function writeSignal(pid){ try{ fs.writeFileSync(OUT,`started pid=${pid} ts=${Date.now()}`); }catch(e){}
}
app.whenReady().then(()=>{
  // attempt to create a hidden window but do not fail startup if it fails
  try{ if (process.env.NODE_ENV !== 'test') new BrowserWindow({show:false}); }catch(e){}
  writeSignal(process.pid);
});
['SIGINT','SIGTERM'].forEach(s=>process.on(s,()=>{ try{ app.quit(); }catch(e){} process.exit(0); }));
app.on('window-all-closed',()=>{});
JS
fi
# renderer placeholder
if [ ! -f renderer/index.js ]; then cat > renderer/index.js <<'JS'
console.log('renderer placeholder');
JS
fi
# webpack config
if [ ! -f webpack.renderer.js ]; then cat > webpack.renderer.js <<'JS'
const path=require('path');
module.exports={target:'web',entry:'./renderer/index.js',output:{path:path.resolve(__dirname,'dist'),filename:'renderer.js'},mode:'production'}
JS
fi
# smoke test
if [ ! -f __tests__/smoke.test.js ]; then cat > __tests__/smoke.test.js <<'JS'
test('arithmetic',()=>{expect(1+1).toBe(2)});
JS
fi
# idempotent start script: prefer local electron binary; do not fallback to npx at runtime
if [ ! -f start.sh ]; then cat > start.sh <<'SH'
#!/usr/bin/env bash
set -euo pipefail
WORKSPACE="/home/kavia/workspace/code-generation/note-organizer-206538-206547/notes_native_app"
cd "$WORKSPACE"
export NODE_ENV=${NODE_ENV:-development}
ELECTRON_BIN="$WORKSPACE/node_modules/.bin/electron"
if [ -x "$ELECTRON_BIN" ]; then exec "$ELECTRON_BIN" .; else echo 'local electron binary not found; run install step to install project devDependencies' >&2; exit 10; fi
SH
chmod +x start.sh
fi
